import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.DGp-bpT-.js";const c=JSON.parse('{"title":"Настройка интеграции с Time Messenger","description":"Подключение SREBot к Time Messenger: создание бота, токен, ID канала и Helm.","frontmatter":{"title":"Настройка интеграции с Time Messenger","description":"Подключение SREBot к Time Messenger: создание бота, токен, ID канала и Helm.","head":[["link",{"rel":"canonical","href":"https://srebot.site360.tech/docs/guide/time-setup.md"}],["link",{"rel":"alternate","hreflang":"ru","href":"https://srebot.site360.tech/docs/guide/time-setup.md"}],["link",{"rel":"alternate","hreflang":"en","href":"https://srebot.site360.tech/docs/en/guide/time-setup.md"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://srebot.site360.tech/docs/guide/time-setup.md"}]]},"headers":[],"relativePath":"guide/time-setup.md","filePath":"guide/time-setup.md","lastUpdated":1785140323000}'),n={name:"guide/time-setup.md"};function l(p,s,h,k,r,o){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="настроика-интеграции-с-time-messenger" tabindex="-1">Настройка интеграции с Time Messenger <a class="header-anchor" href="#настроика-интеграции-с-time-messenger" aria-label="Permalink to &quot;Настройка интеграции с Time Messenger&quot;">​</a></h1><p>SREBot поддерживает корпоративный мессенджер <a href="https://time-messenger.ru/" target="_blank" rel="noreferrer">Time</a> наравне с Telegram, Slack и Discord. Бот читает алерты Alertmanager в выбранном канале, запускает RCA и отвечает в треде инцидента.</p><p>Интеграция работает с Time API v4: новые сообщения поступают через защищенное WebSocket-соединение, а ответы и редактирование сообщений выполняются через REST API.</p><h2 id="_1-создание-бота-в-time" tabindex="-1">1. Создание бота в Time <a class="header-anchor" href="#_1-создание-бота-в-time" aria-label="Permalink to &quot;1. Создание бота в Time&quot;">​</a></h2><p>В пространстве Time должно быть разрешено создание ботов.</p><ol><li>Откройте главное меню Time и выберите <strong>Integrations</strong>.</li><li>Перейдите в <strong>Bot Accounts</strong> и нажмите <strong>Add Bot Account</strong>.</li><li>Укажите имя, username и при необходимости аватар бота.</li><li>После создания скопируйте выданный токен.</li></ol><div class="danger custom-block"><p class="custom-block-title">Сохраните токен</p><p>Time показывает токен бота только один раз. Храните его как секрет и не добавляйте в Git.</p></div><p>Подробности приведены в официальной <a href="https://docs.time-messenger.ru/api/cookbook/create-a-bot/" target="_blank" rel="noreferrer">инструкции по созданию бота</a>.</p><h2 id="_2-добавление-бота-в-канал" tabindex="-1">2. Добавление бота в канал <a class="header-anchor" href="#_2-добавление-бота-в-канал" aria-label="Permalink to &quot;2. Добавление бота в канал&quot;">​</a></h2><p>Добавьте созданного бота в канал, куда Alertmanager отправляет уведомления. Для работы SREBot учетная запись бота должна иметь возможность:</p><ul><li>читать сообщения канала;</li><li>публиковать сообщения и ответы в тредах;</li><li>редактировать и удалять собственные сообщения.</li></ul><p>Запишите строковый ID канала — он используется как <code>TIME_CHANNEL_ID</code>. ID можно получить через Time API или запросить у администратора пространства. Не используйте отображаемое имя канала вместо ID.</p><h2 id="_3-проверка-токена" tabindex="-1">3. Проверка токена <a class="header-anchor" href="#_3-проверка-токена" aria-label="Permalink to &quot;3. Проверка токена&quot;">​</a></h2><p>Проверьте базовый адрес Time и токен запросом к API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail-with-body</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;TIME_TOKEN&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://time.example.com/api/v4/users/me&quot;</span></span></code></pre></div><p>В ответе должны вернуться данные созданного бота. В <code>TIME_BASE_URL</code> указывается только базовый адрес сервера без суффикса <code>/api/v4</code>.</p><h2 id="_4-настроика-srebot" tabindex="-1">4. Настройка SREBot <a class="header-anchor" href="#_4-настроика-srebot" aria-label="Permalink to &quot;4. Настройка SREBot&quot;">​</a></h2><p>Для Docker Compose или запуска через <code>.env</code> задайте:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TIME_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://time.example.com</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TIME_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">replace-with-Time-bot-token</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TIME_CHANNEL_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">replace-with-Time-channel-id</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SAAS_AGENT_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">replace-with-SREBot-agent-token</span></span></code></pre></div><p>Для Helm добавьте учетные данные в <code>values.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  time_base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://time.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  time_token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-bot-token&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  time_channel_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-channel-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  saas_agent_token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-SREBot-agent-token&quot;</span></span></code></pre></div><p>Для production и GitOps рекомендуется заранее создать Kubernetes Secret:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Secret</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">srebot-secret</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Opaque</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stringData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  TIME_BASE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://time.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  TIME_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-bot-token&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  TIME_CHANNEL_ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-channel-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  SAAS_AGENT_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-SREBot-agent-token&quot;</span></span></code></pre></div><p>И сослаться на него из <code>values.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  existingSecret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;srebot-secret&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Только одна чат-интеграция</p><p>Один процесс SREBot может использовать только одну платформу. При выборе Time оставьте переменные Telegram, Slack и Discord пустыми, иначе бот завершит запуск с ошибкой конфигурации.</p></div><h2 id="_5-проверка-работы" tabindex="-1">5. Проверка работы <a class="header-anchor" href="#_5-проверка-работы" aria-label="Permalink to &quot;5. Проверка работы&quot;">​</a></h2><p>После запуска в логах должны появиться сообщения о выборе интеграции <code>time</code>, подключении WebSocket и канале, который слушает бот. Затем отправьте тестовый алерт в настроенный канал.</p><p>SREBot создаст отдельный тред для каждой группы алертов. Внутри треда доступны уточняющие вопросы и команды <code>mute</code>, <code>unmute</code>, <code>status</code>. Произвольный диагностический запрос можно начать прямым упоминанием <code>@username</code> бота.</p><p>Если бот не реагирует, проверьте:</p><ul><li>доступ SREBot к <code>TIME_BASE_URL</code> по HTTPS и WebSocket;</li><li>членство бота в канале из <code>TIME_CHANNEL_ID</code>;</li><li>права учетной записи на чтение канала и отправку сообщений;</li><li>что токен принадлежит именно созданному боту и не был отозван;</li><li>что другие чат-интеграции не настроены одновременно.</li></ul>`,31)])])}const E=i(n,[["render",l]]);export{c as __pageData,E as default};
